/*
 * View Transition API circular reveal for theme switches (ported from Myself).
 * expand: the new frame grows from (x,y) over the old one.
 * contract: the old frame shrinks into (x,y), revealing the new one.
 * Browsers without startViewTransition just apply immediately.
 */
export function circularReveal(
  origin: { x: number; y: number },
  apply: () => void,
  direction: 'expand' | 'contract' = 'expand',
): void {
  const doc = document as Document & {
    startViewTransition?: (cb: () => void) => { ready: Promise<void>; finished: Promise<void> };
  };
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (!doc.startViewTransition || reduced) {
    apply();
    return;
  }

  const { x, y } = origin;
  const radius = Math.hypot(Math.max(x, window.innerWidth - x), Math.max(y, window.innerHeight - y));
  const root = document.documentElement;
  root.classList.toggle('vt-contract', direction === 'contract');
  root.style.setProperty('--vt-x', `${x}px`);
  root.style.setProperty('--vt-y', `${y}px`);

  const transition = doc.startViewTransition(apply);
  transition.ready.then(() => {
    const grow = [`circle(0px at ${x}px ${y}px)`, `circle(${radius}px at ${x}px ${y}px)`];
    const anim = root.animate(
      { clipPath: direction === 'expand' ? grow : [...grow].reverse() },
      {
        duration: 650,
        easing: 'cubic-bezier(0.65, 0, 0.35, 1)',
        fill: 'forwards',
        pseudoElement: direction === 'expand' ? '::view-transition-new(root)' : '::view-transition-old(root)',
      },
    );
    // A forwards-filled animation lingers on the root and corrupts the next
    // transition's pseudo element; cancel only after the transition ends.
    transition.finished
      .catch(() => undefined)
      .then(() => {
        anim.cancel();
        root.classList.remove('vt-contract');
      });
  });
}

/** Center of the element that received the event, for reveal origins. */
export function eventOrigin(e: MouseEvent | PointerEvent): { x: number; y: number } {
  const el = e.currentTarget as HTMLElement | null;
  if (!el) return { x: e.clientX, y: e.clientY };
  const r = el.getBoundingClientRect();
  return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
}

/* Theme store: mode x palette, persisted, follows the OS scheme until the
 * user picks one explicitly. Writes derived tokens onto :root. */
import { defineStore } from 'pinia';
import { derivePalette, TOKEN_VARS } from '../theme/derive';
import { DEFAULT_PRESET_ID, THEME_PRESETS } from '../theme/presets';
import type { Palette, ThemeMode, ThemePreset } from '../theme/types';

const STORAGE_KEY = 'nyabula.theme';

interface Persisted {
  mode: ThemeMode | '';
  paletteId: string;
}

function loadPersisted(): Persisted {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) return JSON.parse(raw) as Persisted;
  } catch {
    /* ignore corrupt data */
  }
  return { mode: '', paletteId: '' };
}

function applyToRoot(palette: Palette, mode: ThemeMode): void {
  const root = document.documentElement;
  const colors = palette[mode];
  root.dataset.theme = mode;
  root.dataset.mode = mode;
  root.dataset.palette = palette.id;
  root.style.colorScheme = mode;
  for (const key of Object.keys(TOKEN_VARS) as (keyof typeof TOKEN_VARS)[]) {
    root.style.setProperty(TOKEN_VARS[key], colors[key]);
  }
}

export const useThemeStore = defineStore('nyabula-theme', {
  state: () => ({
    mode: 'dark' as ThemeMode,
    paletteId: DEFAULT_PRESET_ID,
    /** True when the user picked a mode; otherwise we follow the OS. */
    explicitMode: false,
    presets: THEME_PRESETS as ThemePreset[],
    initialized: false,
  }),
  getters: {
    palettes(): Palette[] {
      return this.presets.map(derivePalette);
    },
    palette(): Palette {
      return this.palettes.find((p) => p.id === this.paletteId) ?? this.palettes[0]!;
    },
  },
  actions: {
    init() {
      if (this.initialized) return;
      const saved = loadPersisted();
      const mq = window.matchMedia('(prefers-color-scheme: dark)');
      this.explicitMode = saved.mode === 'light' || saved.mode === 'dark';
      this.mode = this.explicitMode ? (saved.mode as ThemeMode) : mq.matches ? 'dark' : 'light';
      this.paletteId = this.presets.some((p) => p.id === saved.paletteId) ? saved.paletteId : DEFAULT_PRESET_ID;
      mq.addEventListener('change', (e) => {
        if (!this.explicitMode) {
          this.mode = e.matches ? 'dark' : 'light';
          applyToRoot(this.palette, this.mode);
        }
      });
      this.initialized = true;
      applyToRoot(this.palette, this.mode);
    },
    setMode(mode: ThemeMode) {
      this.mode = mode;
      this.explicitMode = true;
      this.persistAndApply();
    },
    toggleMode() {
      this.setMode(this.mode === 'light' ? 'dark' : 'light');
    },
    /** Return to following the OS scheme. */
    followSystem() {
      this.explicitMode = false;
      this.mode = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
      this.persistAndApply();
    },
    setPalette(id: string) {
      if (!this.presets.some((p) => p.id === id)) return;
      this.paletteId = id;
      this.persistAndApply();
    },
    /** Hosts may register extra presets (e.g. plugin-provided brands). */
    registerPreset(preset: ThemePreset) {
      if (!this.presets.some((p) => p.id === preset.id)) this.presets.push(preset);
    },
    persistAndApply() {
      localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ mode: this.explicitMode ? this.mode : '', paletteId: this.paletteId } satisfies Persisted),
      );
      applyToRoot(this.palette, this.mode);
    },
  },
});

/* Global loading state (ported from Myself).
 * boot: first paint (AppLoading: progress bar + circular clip exit).
 * route: navigation (RouteLoading: color wipe) with a readiness latch so the
 * curtain waits for the target page's first data. */
import { defineStore } from 'pinia';

export const useLoadingStore = defineStore('nyabula-loading', {
  state: () => ({
    bootProgress: 0,
    bootDone: false,
    /** Overlay still on screen (including its exit animation). */
    bootOverlayVisible: true,
    bootLabel: '正在唤醒 Nyabula',
    routeLoading: false,
    routeOverlayVisible: false,
    routePending: 0,
    routeMinUntil: 0,
    /** Set true to disable the route curtain (e.g. shallow tab switches). */
    routeCurtainEnabled: true,
  }),
  actions: {
    setBootProgress(p: number) {
      this.bootProgress = Math.min(100, Math.max(this.bootProgress, p));
    },
    setBootLabel(label: string) {
      this.bootLabel = label;
    },
    finishBoot() {
      this.bootProgress = 100;
      this.bootDone = true;
    },
    startRoute() {
      if (!this.routeCurtainEnabled) return;
      this.routeLoading = true;
      this.routeOverlayVisible = true;
      this.routePending = 0;
    },
    /** Pages call this while fetching; returns a release fn. */
    holdRoute(): () => void {
      if (!this.routeLoading) return () => undefined;
      this.routePending += 1;
      let released = false;
      return () => {
        if (released) return;
        released = true;
        this.routePending = Math.max(0, this.routePending - 1);
        this.tryFinishRoute();
      };
    },
    scheduleFinish(minUntil: number) {
      this.routeMinUntil = minUntil;
      window.setTimeout(() => this.tryFinishRoute(), 60);
    },
    tryFinishRoute() {
      if (!this.routeLoading) return;
      if (this.routePending > 0) return;
      const wait = this.routeMinUntil - performance.now();
      if (wait > 0) {
        window.setTimeout(() => this.tryFinishRoute(), wait);
        return;
      }
      this.routeLoading = false;
    },
  },
});

/* Global modal dialog store: replaces native alert/confirm/prompt.
 * Rendered once by <AppModal>. Promise-based API for callers. */
import { defineStore } from 'pinia';

export interface DialogOptions {
  title?: string;
  message?: string;
  confirmText?: string;
  cancelText?: string;
  /** Destructive styling for the confirm button. */
  danger?: boolean;
  /** Prompt mode: show a text field with this initial value. */
  input?: { value?: string; placeholder?: string; label?: string };
}

interface ActiveDialog extends DialogOptions {
  id: number;
  kind: 'alert' | 'confirm' | 'prompt';
  resolve: (v: unknown) => void;
}

let seq = 0;

export const useDialogStore = defineStore('nyabula-dialog', {
  state: () => ({
    active: null as ActiveDialog | null,
    queue: [] as ActiveDialog[],
    /** Present the modal as a bottom sheet (phone form factor). */
    sheetMode: false,
  }),
  actions: {
    push(d: ActiveDialog) {
      if (this.active) this.queue.push(d);
      else this.active = d;
    },
    alert(message: string, opts: DialogOptions = {}): Promise<void> {
      return new Promise((resolve) => {
        this.push({ id: ++seq, kind: 'alert', message, ...opts, resolve: () => resolve() });
      });
    },
    confirm(message: string, opts: DialogOptions = {}): Promise<boolean> {
      return new Promise((resolve) => {
        this.push({ id: ++seq, kind: 'confirm', message, ...opts, resolve: (v) => resolve(Boolean(v)) });
      });
    },
    prompt(message: string, opts: DialogOptions = {}): Promise<string | null> {
      return new Promise((resolve) => {
        this.push({
          id: ++seq,
          kind: 'prompt',
          message,
          input: { value: '', ...(opts.input ?? {}) },
          ...opts,
          resolve: (v) => resolve(v === null ? null : String(v)),
        });
      });
    },
    /** Called by <AppModal> when the user acts. */
    settle(value: unknown) {
      const d = this.active;
      if (!d) return;
      this.active = this.queue.shift() ?? null;
      d.resolve(value);
    },
  },
});

/* Toast / snackbar store. Rendered once by <ToastHost>. */
import { defineStore } from 'pinia';

export type ToastTone = 'info' | 'ok' | 'warn' | 'error';

export interface Toast {
  id: number;
  text: string;
  tone: ToastTone;
  /** Optional action button. */
  action?: { label: string; run: () => void };
  timeoutMs: number;
}

let seq = 0;

/** Map protocol error codes to user-facing Chinese copy. */
export const ERROR_COPY: Record<string, string> = {
  EPERM: '权限不足，此操作需要更高角色',
  EAUTH: '未认证或令牌失效，请重新配对',
  EINVAL: '参数无效',
  ENOTFOUND: '目标不存在',
  EBUSY: '设备正忙，请稍后重试',
  EOFFLINE: '设备离线',
  ECONFLICT: '发生冲突',
  ENETWORK: '无法连接服务器',
  ETIMEOUT: '请求超时',
};

export function describeError(e: unknown): string {
  if (e && typeof e === 'object') {
    const code = (e as { code?: string }).code;
    const msg = (e as { message?: string }).message;
    if (code && ERROR_COPY[code]) return ERROR_COPY[code] + (msg ? `（${msg}）` : '');
    if (msg) return msg;
  }
  return String(e);
}

export const useToastStore = defineStore('nyabula-toast', {
  state: () => ({ items: [] as Toast[] }),
  actions: {
    show(text: string, tone: ToastTone = 'info', opts: Partial<Pick<Toast, 'action' | 'timeoutMs'>> = {}) {
      const t: Toast = { id: ++seq, text, tone, timeoutMs: opts.timeoutMs ?? (tone === 'error' ? 6000 : 3500), action: opts.action };
      this.items.push(t);
      if (this.items.length > 4) this.items.shift();
      window.setTimeout(() => this.dismiss(t.id), t.timeoutMs);
      return t.id;
    },
    ok(text: string) {
      return this.show(text, 'ok');
    },
    warn(text: string) {
      return this.show(text, 'warn');
    },
    error(e: unknown, prefix?: string) {
      const text = describeError(e);
      return this.show(prefix ? `${prefix}：${text}` : text, 'error');
    },
    dismiss(id: number) {
      this.items = this.items.filter((t) => t.id !== id);
    },
  },
});

/* Motion tokens + shared transitions (ported from Myself). */
:root {
  --dur-fast: 0.2s;
  --dur: 0.35s;
  --dur-slow: 0.6s;
  --ease-out: cubic-bezier(0.2, 0.8, 0.3, 1);
  --ease-spring: cubic-bezier(0.2, 0.8, 0.3, 1.2);
  --ease-inout: cubic-bezier(0.65, 0, 0.35, 1);
}

/* Route transitions */
.page-enter-active {
  transition: opacity var(--dur) var(--ease-out), transform var(--dur) var(--ease-out);
}
.page-leave-active {
  transition: opacity var(--dur-fast) ease;
}
.page-enter-from {
  opacity: 0;
  transform: translateY(18px);
}
.page-leave-to {
  opacity: 0;
}

/* Stack navigation (phone): push from right / pop to right */
.stack-push-enter-active,
.stack-push-leave-active,
.stack-pop-enter-active,
.stack-pop-leave-active {
  transition: transform var(--dur) var(--ease-out), opacity var(--dur) var(--ease-out);
  position: absolute;
  inset: 0;
}
.stack-push-enter-from {
  transform: translateX(100%);
}
.stack-push-leave-to {
  transform: translateX(-24%);
  opacity: 0.4;
}
.stack-pop-enter-from {
  transform: translateX(-24%);
  opacity: 0.4;
}
.stack-pop-leave-to {
  transform: translateX(100%);
}

/* Scroll reveal (v-reveal) */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity var(--dur-slow) var(--ease-out), transform var(--dur-slow) var(--ease-out);
}
.reveal.reveal-in {
  opacity: 1;
  transform: none;
}

/* Hover lift with primary glow */
.hover-lift {
  transition: transform var(--dur-fast) var(--ease-out), box-shadow var(--dur) ease;
}
.hover-lift:hover {
  transform: translateY(-2px);
  box-shadow: var(--md-elev-2), 0 12px 32px -8px rgba(var(--md-primary-rgb), 0.35);
}

/* Fade / scale helpers */
.fade-enter-active,
.fade-leave-active {
  transition: opacity var(--dur-fast) ease;
}
.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}
.pop-enter-active {
  transition: opacity var(--dur-fast) ease, transform var(--dur-fast) var(--ease-spring);
}
.pop-leave-active {
  transition: opacity var(--dur-fast) ease, transform var(--dur-fast) ease;
}
.pop-enter-from,
.pop-leave-to {
  opacity: 0;
  transform: scale(0.94);
}

/* View transition: clip presets so the first frame does not flash */
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}
html:not(.vt-contract)::view-transition-new(root) {
  clip-path: circle(0px at var(--vt-x, 50%) var(--vt-y, 50%));
}
html.vt-contract::view-transition-old(root) {
  z-index: 1;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

/* v-reveal: adds .reveal on mount and .reveal-in when scrolled into view. */
import type { Directive } from 'vue';

const observed = new WeakMap<Element, IntersectionObserver>();

export const vReveal: Directive<HTMLElement, number | undefined> = {
  mounted(el, binding) {
    el.classList.add('reveal');
    if (typeof binding.value === 'number') el.style.transitionDelay = `${binding.value}ms`;
    if (!('IntersectionObserver' in window)) {
      el.classList.add('reveal-in');
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            el.classList.add('reveal-in');
            io.disconnect();
            observed.delete(el);
          }
        }
      },
      { threshold: 0.12 },
    );
    io.observe(el);
    observed.set(el, io);
  },
  unmounted(el) {
    observed.get(el)?.disconnect();
    observed.delete(el);
  },
};

