/* Form factor resolution: pointer coarseness + shortest viewport side +
 * orientation + manual override. Drives shell and page-variant selection;
 * CSS only fine-tunes inside a variant. */
import { computed, onBeforeUnmount, onMounted, reactive, readonly } from 'vue';

export type FormFactor = 'desktop' | 'tablet' | 'phone';
export type Orientation = 'landscape' | 'portrait';

const OVERRIDE_KEY = 'nyabula.formFactor';

const state = reactive({
  width: typeof window !== 'undefined' ? window.innerWidth : 1280,
  height: typeof window !== 'undefined' ? window.innerHeight : 800,
  coarse: typeof window !== 'undefined' ? window.matchMedia('(pointer: coarse)').matches : false,
  override: (typeof localStorage !== 'undefined' ? (localStorage.getItem(OVERRIDE_KEY) as FormFactor | null) : null) ?? null,
});

function measure(): void {
  state.width = window.innerWidth;
  state.height = window.innerHeight;
  state.coarse = window.matchMedia('(pointer: coarse)').matches;
}

let listeners = 0;

export function detectFormFactor(width: number, height: number, coarse: boolean): FormFactor {
  const short = Math.min(width, height);
  const long = Math.max(width, height);
  if (short < 600) return 'phone';
  // Wide + fine pointer = desktop; wide + coarse pointer stays tablet unless very large.
  if (short >= 900 && (!coarse || long >= 1600)) return 'desktop';
  if (short >= 600) return coarse ? 'tablet' : long >= 1100 ? 'desktop' : 'tablet';
  return 'tablet';
}

export function useFormFactor() {
  onMounted(() => {
    if (listeners++ === 0) {
      window.addEventListener('resize', measure, { passive: true });
      window.addEventListener('orientationchange', measure);
    }
    measure();
  });
  onBeforeUnmount(() => {
    if (--listeners === 0) {
      window.removeEventListener('resize', measure);
      window.removeEventListener('orientationchange', measure);
    }
  });

  const auto = computed<FormFactor>(() => detectFormFactor(state.width, state.height, state.coarse));
  const formFactor = computed<FormFactor>(() => state.override ?? auto.value);
  const orientation = computed<Orientation>(() => (state.width >= state.height ? 'landscape' : 'portrait'));
  const pointer = computed<'coarse' | 'fine'>(() => (state.coarse ? 'coarse' : 'fine'));

  function setOverride(v: FormFactor | null): void {
    state.override = v;
    if (v) localStorage.setItem(OVERRIDE_KEY, v);
    else localStorage.removeItem(OVERRIDE_KEY);
  }

  return {
    formFactor,
    auto,
    orientation,
    pointer,
    override: computed(() => state.override),
    setOverride,
    viewport: readonly(state),
    isDesktop: computed(() => formFactor.value === 'desktop'),
    isTablet: computed(() => formFactor.value === 'tablet'),
    isPhone: computed(() => formFactor.value === 'phone'),
  };
}

/* Nyabula Cloud HTTP API client (/api/v1). Contract: Shared/protocol/cloud.md.
 * Bearer ***REDACTED*** persisted in localStorage; errors normalised to ApiError. */

const TOKEN_KEY = 'nyacloud.token';
const BASE = '/api/v1';

export interface User {
  id?: string;
  email: string;
  name: string;
}
export interface CloudDevice {
  deviceId: string;
  name: string;
  online: boolean;
  claimedAt: string;
  coreVersion: string;
  lastSeen: string;
}
export interface DailyStat {
  date: string;
  onlineSeconds: number;
  framesUp: number;
  framesDown: number;
}
export interface DeviceStats {
  daily: DailyStat[];
  current: { online: boolean; clients: number };
}
export interface Overview {
  devices: number;
  online: number;
  clients: number;
  framesToday: number;
}

export class ApiError extends Error {
  constructor(
    public code: string,
    message: string,
    public status: number,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

export function getCloudToken(): string | null {
  return localStorage.getItem(TOKEN_KEY);
}
export function setCloudToken(token: string | null): void {
  if (token) localStorage.setItem(TOKEN_KEY, token);
  else localStorage.removeItem(TOKEN_KEY);
}

/** Relay WebSocket URL for a claimed device (cloud.md §3). */
export function relayUrl(deviceId: string): string {
  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
  const token = getCloudToken() ?? '';
  return `${proto}://${location.host}${BASE}/relay/${encodeURIComponent(deviceId)}?token=${encodeURIComponent(token)}`;
}

async function req<T>(method: string, path: string, body?: unknown): Promise<T> {
  const headers: Record<string, string> = {};
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  const token = getCloudToken();
  if (token) headers['Authorization'] = `Bearer ${token}`;
  let resp: Response;
  try {
    resp = await fetch(BASE + path, { method, headers, body: body !== undefined ? JSON.stringify(body) : undefined });
  } catch {
    throw new ApiError('ENETWORK', '无法连接 Nyabula Cloud', 0);
  }
  let data: unknown = null;
  const text = await resp.text();
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      /* tolerate non-JSON */
    }
  }
  if (!resp.ok) {
    const err = (data as { error?: { code?: string; message?: string } } | null)?.error;
    throw new ApiError(err?.code ?? `EHTTP${resp.status}`, err?.message ?? resp.statusText, resp.status);
  }
  return (data ?? {}) as T;
}

export const cloudApi = {
  register: (email: string, password: string, name: string) =>
    req<{ token: string; user: User }>('POST', '/auth/register', { email, password, name }),
  login: (email: string, password: string) => req<{ token: string; user: User }>('POST', '/auth/login', { email, password }),
  me: () => req<{ user: User }>('GET', '/auth/me'),
  listDevices: () => req<{ devices: CloudDevice[] }>('GET', '/devices'),
  claimDevice: (deviceId: string, claimCode: string) =>
    req<{ device: CloudDevice }>('POST', '/devices/claim', { deviceId, claimCode }),
  unclaimDevice: (deviceId: string) => req<Record<string, never>>('DELETE', `/devices/${encodeURIComponent(deviceId)}`),
  deviceStats: (deviceId: string) => req<DeviceStats>('GET', `/devices/${encodeURIComponent(deviceId)}/stats`),
  overview: () => req<Overview>('GET', '/stats/overview'),
};

/* Device session: one NyaLink connection at a time, addressed by a deviceKey.
 *   lan:<host>:<port>   direct LAN WebSocket
 *   cloud:<deviceId>    Cloud relay (identical NyaLink semantics)
 * Pages never branch on the transport; only the URL builder does.
 * Also keeps the "known devices" list for the connect screen. */
import { defineStore } from 'pinia';
import { computed, ref, shallowRef } from 'vue';
import { NyaLinkClient, type ConnState, type DeviceInfo } from '@nyabula/nyalink';
import { relayUrl } from '../api/cloud';

export type Transport = 'lan' | 'cloud';

export interface KnownDevice {
  key: string;
  transport: Transport;
  label: string;
  /** lan: host:port; cloud: deviceId */
  address: string;
  lastSeen: number;
  deviceId?: string;
  coreVersion?: string;
}

const KNOWN_KEY = 'nyabula.devices';
const LAST_KEY = 'nyabula.lastDevice';
const TOKEN_PREFIX = 'nyalink.token:';

export function parseDeviceKey(key: string): { transport: Transport; address: string } | null {
  const i = key.indexOf(':');
  if (i < 0) return null;
  const transport = key.slice(0, i);
  const address = key.slice(i + 1);
  if ((transport !== 'lan' && transport !== 'cloud') || !address) return null;
  return { transport, address };
}

export function lanKey(host: string, port = 7788): string {
  return `lan:${host}:${port}`;
}
export function cloudKey(deviceId: string): string {
  return `cloud:${deviceId}`;
}

function wsUrlFor(key: string): string | null {
  const parsed = parseDeviceKey(key);
  if (!parsed) return null;
  if (parsed.transport === 'cloud') return relayUrl(parsed.address);
  // lan: allow "host:port" or a full ws:// URL
  if (/^wss?:\/\//.test(parsed.address)) return parsed.address;
  return `ws://${parsed.address}/nyalink`;
}

function loadKnown(): KnownDevice[] {
  try {
    const raw = localStorage.getItem(KNOWN_KEY);
    if (raw) return JSON.parse(raw) as KnownDevice[];
  } catch {
    /* ignore */
  }
  return [];
}

export const useSessionStore = defineStore('session', () => {
  const client = shallowRef<NyaLinkClient | null>(null);
  const deviceKey = ref<string | null>(null);
  const state = ref<ConnState>('idle');
  const device = ref<DeviceInfo | null>(null);
  const role = ref<'owner' | 'family' | 'guest' | null>(null);
  const lastError = ref<string | null>(null);
  const known = ref<KnownDevice[]>(loadKnown());
  const lastDeviceKey = ref<string | null>(localStorage.getItem(LAST_KEY));

  const transport = computed<Transport | null>(() => (deviceKey.value ? parseDeviceKey(deviceKey.value)?.transport ?? null : null));
  const connected = computed(() => state.value === 'connected');
  const online = computed(() => state.value === 'connected' || state.value === 'pairing-required' || state.value === 'authenticating');
  const isOwner = computed(() => role.value === 'owner');
  const canControl = computed(() => role.value === 'owner' || role.value === 'family');

  function persistKnown(): void {
    localStorage.setItem(KNOWN_KEY, JSON.stringify(known.value.slice(0, 20)));
  }

  function remember(key: string, patch: Partial<KnownDevice> = {}): void {
    const parsed = parseDeviceKey(key);
    if (!parsed) return;
    const existing = known.value.find((d) => d.key === key);
    const entry: KnownDevice = existing ?? {
      key,
      transport: parsed.transport,
      address: parsed.address,
      label: parsed.address,
      lastSeen: Date.now(),
    };
    Object.assign(entry, patch, { lastSeen: Date.now() });
    known.value = [entry, ...known.value.filter((d) => d.key !== key)];
    persistKnown();
  }

  function forgetKnown(key: string): void {
    known.value = known.value.filter((d) => d.key !== key);
    persistKnown();
    const url = wsUrlFor(key);
    if (url) localStorage.removeItem(TOKEN_PREFIX + tokenScope(key, url));
  }

  /** Token storage scope: cloud keys rotate the session token in the URL, so key by deviceId. */
  function tokenScope(key: string, url: string): string {
    const parsed = parseDeviceKey(key);
    return parsed?.transport === 'cloud' ? `cloud:${parsed.address}` : url;
  }

  function connect(key: string): boolean {
    const url = wsUrlFor(key);
    if (!url) return false;
    if (client.value && deviceKey.value === key && (state.value === 'connected' || state.value === 'connecting' || state.value === 'authenticating')) {
      return true;
    }
    disconnect();
    deviceKey.value = key;
    lastError.value = null;
    const scope = tokenScope(key, url);
    const c = new NyaLinkClient({
      clientKind: 'web',
      version: '0.2.0',
      loadToken: () => localStorage.getItem(TOKEN_PREFIX + scope),
      saveToken: (_u, token) => localStorage.setItem(TOKEN_PREFIX + scope, token),
    });
    c.onStateChange((s) => {
      state.value = s;
      if (s === 'connected') {
        device.value = c.device;
        role.value = (c.role as typeof role.value) ?? null;
        remember(key, { label: c.device?.name ?? undefined, deviceId: c.device?.id, coreVersion: c.device?.coreVersion });
        localStorage.setItem(LAST_KEY, key);
        lastDeviceKey.value = key;
      }
    });
    client.value = c;
    c.connect(url);
    remember(key);
    return true;
  }

  async function pair(code: string, name = 'Nyabula Web'): Promise<void> {
    lastError.value = null;
    try {
      await client.value?.pair(code, name);
    } catch (e) {
      lastError.value = e instanceof Error ? e.message : String(e);
      throw e;
    }
  }

  function disconnect(): void {
    client.value?.close();
    client.value = null;
    state.value = 'idle';
    device.value = null;
    role.value = null;
  }

  function forgetCurrent(): void {
    const key = deviceKey.value;
    disconnect();
    if (key) forgetKnown(key);
    deviceKey.value = null;
  }

  /** Request that surfaces errors. Rejects immediately while offline. */
  function request(topic: string, data: Record<string, unknown> = {}): Promise<Record<string, unknown>> {
    const c = client.value;
    if (!c || state.value !== 'connected') {
      return Promise.reject(Object.assign(new Error('设备未连接'), { code: 'EOFFLINE' }));
    }
    return c.request(topic, data);
  }

  function onEvent(topic: string, cb: (data: Record<string, unknown>) => void): () => void {
    const c = client.value;
    if (!c) return () => undefined;
    return c.on(topic, cb);
  }

  const clockOffsetMs = () => client.value?.clockOffsetMs ?? 0;

  return {
    client,
    deviceKey,
    transport,
    state,
    device,
    role,
    lastError,
    known,
    lastDeviceKey,
    connected,
    online,
    isOwner,
    canControl,
    connect,
    pair,
    disconnect,
    forgetCurrent,
    forgetKnown,
    remember,
    request,
    onEvent,
    clockOffsetMs,
  };
});

/* Eye domain: latest authoritative eye.state plus optimistic mode/scene
 * intent. Subscribes when the session client changes. */
import { defineStore } from 'pinia';
import { computed, ref, shallowRef, watch } from 'vue';
import type { EyeState } from '@nyabula/eye-engine';
import { useSessionStore } from './session';
import { useToastStore } from '@nyabula/ui';

export type SceneStyle = 'full' | 'minimal';

export const MODE_LABELS: Record<string, string> = {
  idle: '待机', curious: '好奇', happy: '开心', processing: '思考', star: '星星眼', heart: '爱心眼',
  sleepy: '困倦', sleep: '睡眠', angry: '生气', sad: '委屈', surprise: '惊讶', dizzy: '眩晕', derp: '呆萌',
};

export const SCENE_META: Record<string, { label: string; icon: string; group: string }> = {
  music: { label: '音乐', icon: 'music_note', group: '媒体' },
  audio: { label: '音频路由', icon: 'volume_up', group: '媒体' },
  eq: { label: '均衡器', icon: 'tune', group: '媒体' },
  subwoofer: { label: '低音炮', icon: 'subwoofer', group: '媒体' },
  caption: { label: '字幕', icon: 'article', group: '媒体' },
  call: { label: '通话', icon: 'call', group: '通讯' },
  presence: { label: '在场', icon: 'presence', group: '通讯' },
  companion: { label: '陪伴', icon: 'companion', group: '通讯' },
  timer: { label: '倒计时', icon: 'timer', group: '时间' },
  stopwatch: { label: '秒表', icon: 'schedule', group: '时间' },
  alarm: { label: '闹钟', icon: 'alarm', group: '时间' },
  calendar: { label: '日历', icon: 'calendar', group: '时间' },
  'sleep-timer': { label: '睡眠定时', icon: 'moon', group: '时间' },
  weather: { label: '天气', icon: 'cloud', group: '信息' },
  briefing: { label: '简报', icon: 'article', group: '信息' },
  task: { label: '任务', icon: 'task_alt', group: '信息' },
  memory: { label: '记忆', icon: 'memory', group: '信息' },
  health: { label: '健康', icon: 'heart_rate', group: '信息' },
  battery: { label: '电量', icon: 'battery', group: '系统' },
  network: { label: '网络', icon: 'wifi', group: '系统' },
  devices: { label: '设备', icon: 'devices', group: '系统' },
  system: { label: '系统', icon: 'system', group: '系统' },
  privacy: { label: '隐私', icon: 'privacy', group: '系统' },
  identity: { label: '身份', icon: 'identity', group: '系统' },
  home: { label: '家居', icon: 'home', group: '系统' },
  sleep: { label: '休眠', icon: 'moon', group: '系统' },
  pairing: { label: '配对', icon: 'qr_code', group: '系统' },
};

export const SCENE_GROUPS = ['媒体', '通讯', '时间', '信息', '系统'];

export const useEyeStore = defineStore('eye', () => {
  const session = useSessionStore();
  const toast = useToastStore();
  const lastState = shallowRef<EyeState | null>(null);
  const pendingMode = ref<string | null>(null);
  const pendingScene = ref<string | null | undefined>(undefined);
  const sceneStyle = ref<SceneStyle>('full');
  /** Local-only preview of ambient light (no device topic yet). */
  const lightPreview = ref(55);

  let unsub: (() => void) | null = null;
  watch(
    () => session.client,
    (c) => {
      unsub?.();
      unsub = null;
      lastState.value = null;
      if (!c) return;
      unsub = c.on('eye.state', (data) => {
        lastState.value = data as unknown as EyeState;
        pendingMode.value = null;
        pendingScene.value = undefined;
        const sc = (data as { scene?: { style?: string } }).scene;
        if (sc?.style === 'full' || sc?.style === 'minimal') sceneStyle.value = sc.style;
      });
    },
    { immediate: true },
  );

  const activeMode = computed(() => pendingMode.value ?? lastState.value?.expression?.mode ?? 'idle');
  const activeScene = computed<string | null>(() =>
    pendingScene.value !== undefined ? pendingScene.value : lastState.value?.scene?.type ?? null,
  );

  async function setMode(mode: string): Promise<void> {
    const prev = pendingMode.value;
    pendingMode.value = mode;
    pendingScene.value = null;
    try {
      await session.request('eye.mode', { mode });
    } catch (e) {
      pendingMode.value = prev;
      pendingScene.value = undefined;
      toast.error(e, '切换表情失败');
    }
  }

  async function setScene(type: string | null, style: SceneStyle = sceneStyle.value, payload?: Record<string, unknown>, options?: Record<string, unknown>): Promise<void> {
    pendingScene.value = type;
    if (type) sceneStyle.value = style;
    try {
      const data: Record<string, unknown> = { type };
      if (type) {
        data.style = style;
        if (payload) data.payload = payload;
        if (options) data.options = options;
      }
      await session.request('eye.scene', data);
    } catch (e) {
      pendingScene.value = undefined;
      toast.error(e, '切换场景失败');
    }
  }

  function toggleScene(type: string): Promise<void> {
    return activeScene.value === type ? setScene(null) : setScene(type);
  }

  function look(data: { x?: number; y?: number; release?: boolean; hold?: number }): void {
    void session.request('eye.look', data).catch(() => undefined);
  }

  return { lastState, activeMode, activeScene, sceneStyle, lightPreview, setMode, setScene, toggleScene, look };
});

/* Cloud account domain (HTTP). */
import { defineStore } from 'pinia';
import { computed, ref } from 'vue';
import { cloudApi, getCloudToken, setCloudToken, type CloudDevice, type Overview, type User } from '../api/cloud';

export const useAccountStore = defineStore('account', () => {
  const user = ref<User | null>(null);
  const devices = ref<CloudDevice[]>([]);
  const overview = ref<Overview | null>(null);
  const loading = ref(false);
  const checked = ref(false);

  const loggedIn = computed(() => !!user.value);

  async function restore(): Promise<void> {
    if (checked.value) return;
    checked.value = true;
    if (!getCloudToken()) return;
    try {
      user.value = (await cloudApi.me()).user;
    } catch {
      setCloudToken(null);
      user.value = null;
    }
  }

  async function login(email: string, password: string): Promise<void> {
    const r = await cloudApi.login(email, password);
    setCloudToken(r.token);
    user.value = r.user;
  }
  async function register(email: string, password: string, name: string): Promise<void> {
    const r = await cloudApi.register(email, password, name);
    setCloudToken(r.token);
    user.value = r.user;
  }
  function logout(): void {
    setCloudToken(null);
    user.value = null;
    devices.value = [];
    overview.value = null;
  }

  async function refreshDevices(): Promise<void> {
    loading.value = true;
    try {
      devices.value = (await cloudApi.listDevices()).devices;
    } finally {
      loading.value = false;
    }
  }
  async function refreshOverview(): Promise<void> {
    overview.value = await cloudApi.overview();
  }
  async function claim(deviceId: string, claimCode: string): Promise<CloudDevice> {
    const r = await cloudApi.claimDevice(deviceId, claimCode);
    await refreshDevices();
    return r.device;
  }
  async function unclaim(deviceId: string): Promise<void> {
    await cloudApi.unclaimDevice(deviceId);
    await refreshDevices();
  }

  return { user, devices, overview, loading, loggedIn, restore, login, register, logout, refreshDevices, refreshOverview, claim, unclaim };
});

/* Plugin domain: plugin.list cache, per-plugin ui.tree cache with ui.patch
 * application, grant/revoke. */
import { defineStore } from 'pinia';
import { ref, watch } from 'vue';
import { applyPatches, type NyaUiPatch, type NyaUiTree } from '@nyabula/nyaui-vue';
import { useToastStore } from '@nyabula/ui';
import { useSessionStore } from './session';

export interface PluginPermission {
  name: string;
  granted: boolean;
}
export interface PluginInfo {
  id: string;
  name: string;
  version?: string;
  state?: string;
  icon?: string;
  ui?: string[];
  permissions?: PluginPermission[];
  /** v1.1 proposal: host surfaces beyond "page". */
  surfaces?: string[];
  actions?: { id: string; label: string; icon?: string; command: string }[];
}

export const usePluginsStore = defineStore('plugins', () => {
  const session = useSessionStore();
  const toast = useToastStore();
  const list = ref<PluginInfo[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const trees = ref<Record<string, NyaUiTree>>({});
  const treeVersion = ref(0);

  let unsub: (() => void) | null = null;
  watch(
    () => session.client,
    (c) => {
      unsub?.();
      unsub = null;
      list.value = [];
      trees.value = {};
      if (!c) return;
      unsub = c.on('ui.patch', (data) => {
        const id = String(data.pluginId ?? '');
        const tree = trees.value[id];
        if (!tree) return;
        const patches = (data.patches ?? []) as NyaUiPatch[];
        if (!applyPatches(tree, patches)) void loadTree(id, true);
        else treeVersion.value++;
      });
    },
    { immediate: true },
  );

  async function refresh(): Promise<void> {
    loading.value = true;
    error.value = null;
    try {
      const r = await session.request('plugin.list');
      list.value = (r.plugins ?? []) as PluginInfo[];
    } catch (e) {
      error.value = e instanceof Error ? e.message : String(e);
    } finally {
      loading.value = false;
    }
  }

  async function loadTree(pluginId: string, force = false, surface?: string): Promise<NyaUiTree | null> {
    const key = surface ? `${pluginId}#${surface}` : pluginId;
    if (!force && trees.value[key]) return trees.value[key]!;
    const data: Record<string, unknown> = { pluginId };
    if (surface) data.surface = surface;
    const tree = (await session.request('ui.tree', data)) as unknown as NyaUiTree;
    trees.value[key] = tree;
    treeVersion.value++;
    return tree;
  }

  async function sendEvent(pluginId: string, cmd: { componentId: string; event: string; command?: string; args?: unknown; values?: unknown }): Promise<boolean> {
    const data: Record<string, unknown> = { pluginId, componentId: cmd.componentId, event: cmd.event, values: cmd.values };
    if (cmd.command !== undefined) data.command = cmd.command;
    if (cmd.args !== undefined) data.args = cmd.args;
    try {
      await session.request('ui.event', data);
      return true;
    } catch (e) {
      toast.error(e, '插件操作失败');
      return false;
    }
  }

  async function setPermission(pluginId: string, permission: string, granted: boolean): Promise<boolean> {
    const p = list.value.find((x) => x.id === pluginId)?.permissions?.find((x) => x.name === permission);
    const prev = p?.granted;
    if (p) p.granted = granted;
    try {
      await session.request(granted ? 'plugin.grant' : 'plugin.revoke', { pluginId, permission });
      toast.ok(granted ? `已授予 ${permission}` : `已撤销 ${permission}`);
      return true;
    } catch (e) {
      if (p && prev !== undefined) p.granted = prev;
      toast.error(e, '权限变更失败');
      return false;
    }
  }

  return { list, loading, error, trees, treeVersion, refresh, loadTree, sendEvent, setPermission };
});

