  loading.setBootLabel('加载字体');
  await (document.fonts?.ready ?? Promise.resolve());
  loading.setBootProgress(45);
  loading.setBootLabel('恢复会话');
  await useAccountStore().restore().catch(() => undefined);
  loading.setBootProgress(70);
