/* Shell helpers shared by the three layouts: current nav id, device-scoped
 * navigation, connection tone/label. */
import { computed } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { PRIMARY_NAV, type NavItem } from '../nav';
import { useSessionStore } from '../stores/session';

export function useShell() {
  const route = useRoute();
  const router = useRouter();
  const session = useSessionStore();

  const activeNav = computed(() => (route.meta.nav as string | undefined) ?? (route.name === 'connect' ? 'connect' : undefined));
  const inDevice = computed(() => typeof route.params.key === 'string');
  const deviceKey = computed(() => session.deviceKey ?? session.lastDeviceKey);

  function go(item: NavItem): void {
    if (item.to.startsWith('/')) {
      void router.push(item.to);
      return;
    }
    const key = deviceKey.value;
    if (!key) {
      void router.push({ name: 'connect' });
      return;
    }
    void router.push({ name: item.to, params: { key } });
  }

  const connTone = computed<'ok' | 'busy' | 'off'>(() => {
    switch (session.state) {
      case 'connected':
        return 'ok';
      case 'connecting':
      case 'authenticating':
      case 'reconnecting':
      case 'pairing-required':
        return 'busy';
      default:
        return 'off';
    }
  });
  const connLabel = computed(() => {
    const labels: Record<string, string> = {
      idle: '未连接',
      connecting: '连接中',
      authenticating: '认证中',
      'pairing-required': '待配对',
      connected: session.device?.name ?? '已连接',
      reconnecting: '重连中',
      closed: '已断开',
    };
    return labels[session.state] ?? session.state;
  });

  const title = computed(() => (route.meta.title as string | undefined) ?? 'Nyabula');
  const depth = computed(() => (typeof route.meta.depth === 'number' ? route.meta.depth : 0));

  function back(): void {
    if (window.history.length > 1) router.back();
    else if (activeNav.value && deviceKey.value) void router.push({ name: activeNav.value, params: { key: deviceKey.value } });
    else void router.push({ name: 'connect' });
  }

  return { nav: PRIMARY_NAV, activeNav, inDevice, deviceKey, go, connTone, connLabel, title, depth, back, session, route };
}

/* Host extension registry: the seam for Core plugins to grow into the UI.
 * Contributions are plain objects; pages query by surface and form factor.
 *
 *   surface 'page'        plugin page (NyaUI tree; built-in)
 *   surface 'widget'      card on the eye / services pages (nyaui.md v1.1)
 *   surface 'quickAction' command palette / quick bar entries
 *   surface 'settings'    section under Device
 *   surface 'route'       fully custom Vue route under /d/:key/x/<id>
 */
import { reactive, type Component } from 'vue';
import type { FormFactor } from '../composables/useFormFactor';

export type Surface = 'page' | 'widget' | 'quickAction' | 'settings' | 'route';

export interface HostCommand {
  id: string;
  label: string;
  icon?: string;
  group?: string;
  run: () => void | Promise<unknown>;
}

export interface WidgetContribution {
  id: string;
  title: string;
  icon?: string;
  /** Vue component or a NyaUI tree provider. */
  component?: Component;
  pluginId?: string;
  /** Which form factors show it (default all). */
  formFactors?: FormFactor[];
  /** Grid size hint: 1 = quarter, 2 = half, 4 = full row. */
  span?: 1 | 2 | 4;
  order?: number;
}

export interface SettingsContribution {
  id: string;
  label: string;
  icon?: string;
  component: Component;
  order?: number;
}

export interface RouteContribution {
  id: string;
  label: string;
  icon?: string;
  component: Component;
}

const state = reactive({
  commands: [] as HostCommand[],
  widgets: [] as WidgetContribution[],
  settings: [] as SettingsContribution[],
  routes: [] as RouteContribution[],
});

function upsert<T extends { id: string }>(list: T[], item: T): () => void {
  const i = list.findIndex((x) => x.id === item.id);
  if (i >= 0) list.splice(i, 1, item);
  else list.push(item);
  return () => {
    const j = list.findIndex((x) => x.id === item.id);
    if (j >= 0) list.splice(j, 1);
  };
}

export const hostRegistry = {
  registerCommand: (c: HostCommand) => upsert(state.commands, c),
  registerWidget: (w: WidgetContribution) => upsert(state.widgets, w),
  registerSettings: (s: SettingsContribution) => upsert(state.settings, s),
  registerRoute: (r: RouteContribution) => upsert(state.routes, r),
  commands: () => state.commands,
  widgets: (ff?: FormFactor) =>
    [...state.widgets].filter((w) => !ff || !w.formFactors || w.formFactors.includes(ff)).sort((a, b) => (a.order ?? 0) - (b.order ?? 0)),
  settings: () => [...state.settings].sort((a, b) => (a.order ?? 0) - (b.order ?? 0)),
  routes: () => state.routes,
};

export type HostRegistry = typeof hostRegistry;

/* Eye page logic shared by all three variants. */
import { computed, ref } from 'vue';
import { MODES, SCENES, type EyeEngine } from '@nyabula/eye-engine';
import { useSessionStore } from '../../stores/session';
import { MODE_LABELS, SCENE_GROUPS, SCENE_META, useEyeStore } from '../../stores/eye';

export function useEyePage() {
  const session = useSessionStore();
  const eye = useEyeStore();
  const pairing = ref(false);
  const pairError = ref<string | null>(null);
  let engine: EyeEngine | null = null;

  const showPairOverlay = computed(() => session.state === 'pairing-required' || (pairing.value && session.state === 'authenticating'));
  const canvasReady = computed(() => session.connected);

  async function doPair(code: string) {
    pairing.value = true;
    pairError.value = null;
    try {
      await session.pair(code, 'Nyabula Web');
    } catch {
      pairError.value = session.lastError && /wrong pairing code|EPERM/i.test(session.lastError) ? '配对码错误' : session.lastError ?? '配对失败';
    } finally {
      pairing.value = false;
    }
  }

  function onEngineReady(e: EyeEngine) {
    engine = e;
    engine.setLight(eye.lightPreview / 100);
  }
  function onLook(d: { x?: number; y?: number; release?: boolean }) {
    eye.look(d);
  }
  function onLight(v: number) {
    eye.lightPreview = v;
    engine?.setLight(v / 100);
  }

  const modes = MODES.map((m) => ({ id: m, label: MODE_LABELS[m] ?? m }));
  const sceneGroups = SCENE_GROUPS.map((g) => ({
    group: g,
    scenes: SCENES.filter((s) => (SCENE_META[s]?.group ?? '系统') === g).map((s) => ({ id: s, label: SCENE_META[s]?.label ?? s, icon: SCENE_META[s]?.icon ?? 'widgets' })),
  })).filter((g) => g.scenes.length);
  const allScenes = SCENES.map((s) => ({ id: s, label: SCENE_META[s]?.label ?? s, icon: SCENE_META[s]?.icon ?? 'widgets' }));

  const stateSummary = computed(() => {
    const s = eye.lastState;
    if (!s) return null;
    return {
      mode: s.expression?.mode,
      gaze: s.gaze?.mode,
      scene: s.scene?.type ?? null,
      style: s.scene?.style,
      light: s.expression?.lightLevel,
      seq: s.seq,
    };
  });

  return { session, eye, pairing, pairError, showPairOverlay, canvasReady, doPair, onEngineReady, onLook, onLight, modes, sceneGroups, allScenes, stateSummary };
}

import { computed, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { useSessionStore, lanKey, cloudKey } from '../../stores/session';
import { useAccountStore } from '../../stores/account';
import { useDialogStore, useToastStore } from '@nyabula/ui';

export function useConnectPage() {
  const session = useSessionStore();
  const account = useAccountStore();
  const router = useRouter();
  const dialog = useDialogStore();
  const toast = useToastStore();

  const host = ref('');
  const port = ref('7788');
  const advanced = ref(false);
  const fullUrl = ref('');
  const connecting = ref(false);
  const error = ref<string | null>(null);

  const known = computed(() => session.known);
  const cloudDevices = computed(() => account.devices);

  function validate(): string | null {
    if (advanced.value) return /^wss?:\/\//.test(fullUrl.value.trim()) ? null : '请输入 ws:// 或 wss:// 开头的完整地址';
    if (!host.value.trim()) return '请输入设备 IP 或主机名';
    const p = Number(port.value);
    if (!Number.isInteger(p) || p < 1 || p > 65535) return '端口无效';
    return null;
  }

  async function connectLan(): Promise<void> {
    error.value = validate();
    if (error.value) return;
    const key = advanced.value ? `lan:${fullUrl.value.trim()}` : lanKey(host.value.trim(), Number(port.value));
    await open(key);
  }

  async function open(key: string): Promise<void> {
    connecting.value = true;
    error.value = null;
    session.connect(key);
    // Wait for a terminal-ish state so the user sees feedback before nav.
    const ok = await waitState(6000);
    connecting.value = false;
    if (!ok) {
      error.value = session.lastError ?? '连接超时，请检查设备是否在线、是否同一局域网';
      toast.error(error.value);
      return;
    }
    await router.push({ name: 'eye', params: { key } });
  }

  function waitState(timeoutMs: number): Promise<boolean> {
    return new Promise((resolve) => {
      const t0 = performance.now();
      const stop = watch(
        () => session.state,
        (s) => {
          if (s === 'connected' || s === 'pairing-required') {
            stop();
            resolve(true);
          } else if (s === 'closed' || (s === 'reconnecting' && performance.now() - t0 > 1500)) {
            stop();
            resolve(false);
          }
        },
        { immediate: true },
      );
      window.setTimeout(() => {
        stop();
        resolve(session.state === 'connected' || session.state === 'pairing-required');
      }, timeoutMs);
    });
  }

  async function openCloud(deviceId: string): Promise<void> {
    await open(cloudKey(deviceId));
  }

  async function forget(key: string): Promise<void> {
    if (await dialog.confirm('将删除本机保存的配对令牌，下次需重新配对。', { title: '忘记该设备？', danger: true, confirmText: '忘记' })) {
      session.forgetKnown(key);
      toast.ok('已忘记设备');
    }
  }

  return { session, account, host, port, advanced, fullUrl, connecting, error, known, cloudDevices, connectLan, open, openCloud, forget };
}

// Three-viewport smoke: load, connect to simulator, pair, screenshot each page.
import { chromium } from 'playwright';
import fs from 'node:fs';

const BASE = process.env.BASE ?? 'http://localhost:5180';
const OUT = process.env.OUT ?? './screens';
const PAIR = process.env.PAIR ?? '';
const PAGES = (process.env.PAGES ?? 'eye,services,plugins,device,agent').split(',');
fs.mkdirSync(OUT, { recursive: true });

const VIEWPORTS = {
  desktop: { width: 1440, height: 900, isMobile: false, hasTouch: false },
  tablet: { width: 1024, height: 768, isMobile: true, hasTouch: true },
  tabletP: { width: 768, height: 1024, isMobile: true, hasTouch: true },
  phone: { width: 390, height: 844, isMobile: true, hasTouch: true },
};

const browser = await chromium.launch();
const errors = [];
for (const [name, vp] of Object.entries(VIEWPORTS)) {
  const ctx = await browser.newContext({ viewport: { width: vp.width, height: vp.height }, isMobile: vp.isMobile, hasTouch: vp.hasTouch, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  page.on('pageerror', (e) => errors.push(`[${name}] pageerror: ${e.message}`));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(`[${name}] console: ${m.text().slice(0, 200)}`); });
  await page.goto(`${BASE}/connect?stay=1`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1800);
  await page.screenshot({ path: `${OUT}/${name}-connect.png` });
  // connect to simulator via URL deep link
  await page.goto(`${BASE}/d/lan:127.0.0.1:7788/eye`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(2500);
  if (PAIR) {
    const input = page.locator('.ghost-input');
    if (await input.count()) {
      await input.fill(PAIR);
      await page.keyboard.press('Enter');
      await page.waitForTimeout(2500);
    }
  }
  for (const p of PAGES) {
    await page.goto(`${BASE}/d/lan:127.0.0.1:7788/${p}`, { waitUntil: 'networkidle' });
    await page.waitForTimeout(1800);
    await page.screenshot({ path: `${OUT}/${name}-${p}.png` });
  }
  await ctx.close();
}
await browser.close();
console.log(errors.length ? errors.join('\n') : 'NO_ERRORS');

