/** Build a favicon data URL for the given mode with the nose in `nose`. */
export function faviconDataUrl(mode: 'light' | 'dark', nose: string): string {
  const svg = (mode === 'dark' ? FAVICON_DARK : FAVICON_LIGHT).replace(/__NOSE__/g, nose);
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
}

/** Point every <link rel="icon"> at a themed favicon. */
export function applyFavicon(mode: 'light' | 'dark', nose: string): void {
  const href = faviconDataUrl(mode, nose);
  let link = document.querySelector<HTMLLinkElement>('link[rel="icon"][data-themed]');
  if (!link) {
    document.querySelectorAll('link[rel="icon"]').forEach((l) => l.remove());
    link = document.createElement('link');
    link.rel = 'icon';
    link.type = 'image/svg+xml';
    link.dataset.themed = '1';
    document.head.appendChild(link);
  }
  link.href = href;
}
